async function ensureCharacterMetadata(){if(characterMetadata)return characterMetadata;if(!characterMetadataPromise){characterMetadataPromise=fetch('/api/character_metadata').then(async r=>{if(!r.ok)throw new Error('character metadata');const data=await r.json();characterMetadata=data.characters||[];characterGroups=Array.isArray(data.groups)?data.groups:[];return characterMetadata;}).finally(()=>{characterMetadataPromise=null;});}return characterMetadataPromise;}
function supportsCharacterForm(cat,form){const n=Number(form);return!!cat&&cat.selectable!==false&&Number.isInteger(n)&&n>=1&&n<=Number(cat.form_count||1)&&!!cat.names?.[n-1];}
