function getFilteredCharacters(tab){if(!characterMetadata)return[];const q=characterQueryFilter[tab].trim().toLowerCase(),form=characterFormFilter[tab],rarity=characterRarityFilter[tab],source=characterSourceFilter[tab],groupId=characterGroupFilter[tab],talentsOnly=state[tab].s3.has('talents_specific');const exactGroup=characterGroups.find(group=>group.id===groupId);const exactSet=exactGroup?groupCatSet(exactGroup):null;const sourceSet=source==='all'?null:new Set(characterGroups.filter(group=>group.kind===source).flatMap(group=>group.cat_ids||[]).map(Number));return characterMetadata.filter(c=>c.selectable!==false&&(!talentsOnly||(c.talents||[]).length)&&c.form_count>=form&&(rarity==='all'||c.rarity===rarity)&&(!exactSet||exactSet.has(c.id))&&(!sourceSet||sourceSet.has(c.id))&&(!q||c.names.some(n=>n.toLowerCase().includes(q))||String(c.id)===q));}
