function sanitizePlaytimeInput(el,errId){let v=el.value.replace(/[^0-9:]/g,'');const firstColon=v.indexOf(':');if(firstColon!==-1){const head=v.slice(0,firstColon).slice(0,4);const tail=v.slice(firstColon+1).replace(/:/g,'').slice(0,2);v=head+':'+tail;}else{v=v.slice(0,4);}
el.value=v;const errEl=document.getElementById(errId);if(errEl)errEl.textContent='';}
function checkPlaytime(el,errId){const errEl=document.getElementById(errId);if(!errEl)return true;if(el.value&&!PLAYTIME_CLIENT_RE.test(el.value)){errEl.textContent='「時間:分」の形式で入力してください（例: 1200:30、分は0〜59）';return false;}
errEl.textContent='';return true;}
function detailedStageCount(tab,type,key){return detailedStageCountMode[tab][type]==='same'?clampStageClearCount(detailedStageBulkCount[tab][type]):clampStageClearCount(detailedStageIndividualCount[tab][type][key]||1);}
function collectMainStoryStages(tab){if(!state[tab].s1.has('main_story_clear'))return undefined;const result={};mainStoryStageSelectionState[tab].forEach(key=>{const[chapter,stage]=key.split(':').map(Number);if(!result[chapter])result[chapter]={};result[chapter][stage]=detailedStageCount(tab,'main_story',key);});return result;}
function collectEventStageSettings(tab){if(!state[tab].s1.has('event_clear'))return undefined;const result={};eventStageSelectionState[tab].forEach(key=>{const[family,map,star,stage]=key.split(':');if(!result[family])result[family]={};if(!result[family][map])result[family][map]={};if(!result[family][map][star])result[family][map][star]={};result[family][map][star][stage]=detailedStageCount(tab,'event',key);});return result;}
function collectLabyrinthCharacters(tab){if(!state[tab].s1.has('event_clear'))return undefined;const settings=labyrinthCharacterState[tab];if(settings.action==='none')return undefined;const ids=new Set(settings.ids);String(settings.manual||'').split(/[,\s]+/).filter(Boolean).forEach(value=>{const id=Number.parseInt(value);if(Number.isInteger(id)&&id>=1&&id<=9999)ids.add(id);});return{action:settings.action,ids:[...ids].sort((a,b)=>a-b)};}
function collectPayload(tab){const selected={};for(const g of GROUPS)selected[g.key]=[...state[tab][g.key]];const charEl=document.getElementById(`char-input-${tab}`);const char_list=charEl?charEl.value.split(',').map(s=>s.trim()).filter(Boolean):[];const custom_amounts={};for(const def of CUSTOM_INPUT_DEFS){const el=document.getElementById(`amt-${tab}-${def.key}`);custom_amounts[def.key]=el?(parseInt(el.value)||0):0;}
const ptEl=document.getElementById(`amt-${tab}-custom_playtime`);const custom_playtime=ptEl?ptEl.value.trim():"";const main_story_chapters=[...new Set([...mainStoryStageSelectionState[tab]].map(key=>Number(key.split(':')[0])))].sort((a,b)=>a-b);const vip_items={};for(const group of VIP_ITEM_GROUPS){const fixedSelected=state[tab].s1.has(group.fixed);const customSelected=state[tab].s4.has(group.custom);if(!fixedSelected&&!customSelected)continue;vip_items[group.key]=Object.fromEntries([...vipItemSelectionState[tab][group.key]].sort((a,b)=>a-b).map(idx=>{const amount=fixedSelected?group.amount:amountModeState[tab][group.key]==='individual'?Math.max(0,Number.parseInt(vipIndividualAmountState[tab][group.key][idx])||0):custom_amounts[group.custom];return[idx,amount];}));}
const fixedEventTickets=state[tab].s1.has('event_tickets');const customEventTickets=state[tab].s4.has('custom_event_tickets');if(fixedEventTickets||customEventTickets){vip_items.event_tickets=Object.fromEntries([...eventTicketSelectionState[tab]].map(ticketId=>{const amount=fixedEventTickets?9999:amountModeState[tab].event_tickets==='individual'?Math.max(0,Math.min(Number.parseInt(eventTicketIndividualAmountState[tab][ticketId])||0,9999)):custom_amounts.custom_event_tickets;return[ticketId,amount];}));}
if(state[tab].s2.has('labyrinth_medals')){vip_items.labyrinth_medals=Object.fromEntries([...labyrinthMedalSelectionState[tab]].sort((a,b)=>a-b).map(medalIndex=>{const amount=amountModeState[tab].labyrinth_medals==='individual'?labyrinthMedalAmountState[tab][medalIndex]:labyrinthMedalBulkState[tab];return[medalIndex,Math.max(0,Math.min(Number.parseInt(amount)||0,32767))];}));}
const legend_stages=collectLegendStages(tab);const vip_facilities=collectVipFacilities(tab);const vip_talent_orbs=collectVipTalentOrbs(tab,custom_amounts);const special_stages=collectSpecialStages(tab);const main_story_stages=collectMainStoryStages(tab);const event_stage_settings=collectEventStageSettings(tab);const labyrinth_characters=collectLabyrinthCharacters(tab);const ototo_settings=collectOtotoSettings(tab);const dojo_score_settings=collectDojoScoreSettings(tab);const future_score_settings=collectFutureScoreSettings(tab);const lineup_settings=state[tab].s3.has('lineup_custom')?{lineup:lineupEditorState[tab].lineup,cats:lineupEditorState[tab].cats.map(catId=>catId===null?null:Number(catId)),forms:lineupEditorState[tab].forms.map((form,index)=>form===null?null:Math.max(1,Math.min(Number(lineupCatById(lineupEditorState[tab].cats[index])?.form_count||1),Number(form)||1)))}:undefined;enrichSelectedCharacters(tab);const character_settings=[...characterSelectionState[tab].values()].filter(item=>supportsCharacterForm(lineupCatById(item.id),item.form)).map(item=>{const selectedTalents=new Set(item.talent_selected||[]);const talents=Object.fromEntries((item.talent_defs||[]).filter(t=>selectedTalents.has(t.id)).map(t=>[t.id,item.talent_mode==='same'?(item.talent_bulk_level===null||item.talent_bulk_level===undefined?t.max_level:item.talent_bulk_level):(item.talent_levels?.[t.id]??t.max_level)]));const range=characterRandomRanges[tab];return{id:item.id,form:item.form,base_level:item.base_level,plus_level:item.plus_level,level_mode:characterLevelMode[tab],base_level_min:range.base_min,base_level_max:range.base_max,plus_level_min:range.plus_min,plus_level_max:range.plus_max,talent_action:item.talent_action||'set',talents};});return{selected,char_list,character_settings,...custom_amounts,custom_playtime,main_story_chapters,vip_items,legend_stages,vip_facilities,vip_talent_orbs,special_stages,main_story_stages,event_stage_settings,labyrinth_characters,lineup_settings,ototo_settings,dojo_score_settings,future_score_settings};}
function validateBeforeSubmit(tab,{requireCodes}={}){if(requireCodes){const prefix=tab==='clone'?'cl':'d';const tcEl=document.getElementById(`${prefix}_transfer_code`);const acEl=document.getElementById(`${prefix}_auth_code`);const tcOk=checkTransferCode(tcEl,`${prefix}_transfer_code_err`);const acOk=checkAuthCode(acEl,`${prefix}_auth_code_err`);if(!tcEl.value||!acEl.value){return'引き継ぎコードと認証番号を入力してください';}
if(!tcOk)return'引き継ぎコードは9桁の16進数（0-9,a-f）で入力してください';if(!acOk)return'認証番号は4桁の数字（0-9）で入力してください';}
if(state[tab]&&state[tab].s4&&state[tab].s4.has('custom_playtime')){const ptEl=document.getElementById(`amt-${tab}-custom_playtime`);const ok=checkPlaytime(ptEl,`playtime-err-${tab}`);if(!ptEl.value)return'プレイ時間（時間:分）を入力してください';if(!ok)return'プレイ時間は「時間:分」の形式で入力してください（例: 1200:30）';}
const labyrinth=labyrinthCharacterState[tab];if(labyrinth&&labyrinth.action.endsWith('_selected')){const manualIds=String(labyrinth.manual||'').split(/[,\s]+/).filter(Boolean);if(!labyrinth.ids.size&&!manualIds.length){return'地底迷宮の指定キャラを、番号またはキャラ名から選択してください';}}
const needsDetailData=Object.values(LEGEND_PARENT_VALUES).some(value=>state[tab]?.s1?.has(value))||state[tab]?.s1?.has('main_story_clear')||state[tab]?.s1?.has('event_clear')||state[tab]?.s1?.has('zombie_clear')||state[tab]?.s1?.has('aku_clear')||state[tab]?.s1?.has('talent_orbs')||state[tab]?.s2?.has('base_upgrades_max')||state[tab]?.s4?.has('custom_talent_orbs')||state[tab]?.s4?.has('custom_base_upgrades');if(needsDetailData&&!legendMetadata){return'ステージ・施設・本能玉データを読み込み中です。読み込み完了後に実行してください';}
if(state[tab]?.s2?.has('ototo_detailed')){if(!ototoMetadata)return'オトート・城強化データを読み込み中です。読み込み完了後に実行してください';if(![...ototoSelectionState[tab].values()].some(item=>item.selected))return'設定する城を1つ以上選択してください';}
if(state[tab]?.s2?.has('future_score_detailed')&&!futureScoreState[tab].selected.size){return'採点スコアを設定する未来編の章を1つ以上選択してください';}
return null;}
async function fetchWithTimeout(url,options={},timeoutMs=45000){const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),timeoutMs);try{return await fetch(url,{...options,signal:controller.signal});}
finally{clearTimeout(timer);}}
function generateOperationId(){const chars='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';const values=new Uint8Array(30);crypto.getRandomValues(values);return[...values].map(v=>chars[v%chars.length]).join('');}
async function submitDaiko(){const err=validateBeforeSubmit('daiko',{requireCodes:true});if(err){alert(err);return;}
const tc=document.getElementById('d_transfer_code').value.trim();const ac=document.getElementById('d_auth_code').value.trim();const btn=document.getElementById('btn-daiko');btn.disabled=true;btn.textContent='認証中...';try{const keyRes=await fetchWithTimeout('/api/get_key',{method:'POST'},15000);if(!keyRes.ok)throw new Error('認証キーを取得できませんでした');const{api_key}=await keyRes.json();const operation_id=generateOperationId();const payload={...collectPayload('daiko'),transfer_code:tc,auth_code:ac,api_key,operation_id};await startJob('daiko','/api/run_daiko',payload,{in_tc:tc,in_ac:ac,operation_id});}catch(e){btn.disabled=false;btn.textContent='代行を実行する';alert('エラーが発生しました');}}
async function submitCreate(){const err=validateBeforeSubmit('create',{requireCodes:false});if(err){alert(err);return;}
const btn=document.getElementById('btn-create');btn.disabled=true;btn.textContent='認証中...';try{const keyRes=await fetchWithTimeout('/api/get_key',{method:'POST'},15000);if(!keyRes.ok)throw new Error('認証キーを取得できませんでした');const{api_key}=await keyRes.json();const count=countState.create;const account_type=accountTypeState.create;const payload={...collectPayload('create'),count,account_type,api_key};await startJob('create','/api/run_create',payload);}catch(e){btn.disabled=false;btn.textContent='アカウントを作成する';alert('エラーが発生しました');}}
async function submitClone(){const err=validateBeforeSubmit('clone',{requireCodes:true});if(err){alert(err);return;}
const tc=document.getElementById('cl_transfer_code').value.trim();const ac=document.getElementById('cl_auth_code').value.trim();const btn=document.getElementById('btn-clone');btn.disabled=true;btn.textContent='認証中...';try{const keyRes=await fetchWithTimeout('/api/get_key',{method:'POST'},15000);if(!keyRes.ok)throw new Error('認証キーを取得できませんでした');const{api_key}=await keyRes.json();const count=countState.clone;const operation_id=generateOperationId();await startJob('clone','/api/run_clone',{transfer_code:tc,auth_code:ac,count,api_key,operation_id},{in_tc:tc,in_ac:ac,operation_id});}catch(e){btn.disabled=false;btn.textContent='複製を実行する';alert('エラーが発生しました');}}
