function resumeSavedJobs(){for(const tab of['daiko','create','clone']){try{const saved=JSON.parse(localStorage.getItem(`${ACTIVE_JOB_KEY_PREFIX}${tab}`)||'null');if(!saved?.job_id||Date.now()-Number(saved.saved_at||0)>30*60*1000){localStorage.removeItem(`${ACTIVE_JOB_KEY_PREFIX}${tab}`);continue;}
if(document.getElementById(`btn-${tab}`)&&document.getElementById(`result-${tab}`)){startJob(tab,null,null,saved.extra||{},saved.job_id,saved.job_token||null);}}catch{localStorage.removeItem(`${ACTIVE_JOB_KEY_PREFIX}${tab}`);}}}
let charDict=null;let charSearchLoading=false;async function openCharSearch(){document.getElementById('charsearch-modal').style.display='block';document.getElementById('charsearch-input').value='';document.getElementById('charsearch-results').innerHTML='';if(!charDict&&!charSearchLoading){await loadCharDict();}else if(charDict){document.getElementById('charsearch-status').textContent=`${Object.keys(charDict).length} キャラクター読み込み済み`;}
setTimeout(()=>document.getElementById('charsearch-input').focus(),100);}
function closeCharSearch(){document.getElementById('charsearch-modal').style.display='none';}
async function loadCharDict(){charSearchLoading=true;const status=document.getElementById('charsearch-status');status.textContent='データを取得中...';try{const res=await fetch('/api/char_dict');if(!res.ok)throw new Error('fetch failed');charDict=await res.json();status.textContent=`${Object.keys(charDict).length} キャラクター読み込み済み`;}catch(e){status.textContent='データ取得に失敗しました';}
charSearchLoading=false;}
function onCharSearchInput(){const query=document.getElementById('charsearch-input').value.trim();const resultsEl=document.getElementById('charsearch-results');if(!charDict){resultsEl.innerHTML='<div style="color:var(--muted);font-size:13px;text-align:center;padding:30px 0;">データ読み込み中...</div>';return;}
if(!query){resultsEl.innerHTML='';return;}
const results=Object.entries(charDict).filter(([name])=>name.includes(query)).sort((a,b)=>parseInt(a[1])-parseInt(b[1]));if(!results.length){resultsEl.innerHTML=`<div style="color:var(--muted);font-size:13px;text-align:center;padding:30px 0;">「${query}」は見つかりませんでした</div>`;return;}
resultsEl.innerHTML=results.map(([name,no])=>`<div style="display:flex;align-items:center;gap:12px;padding:9px 4px;border-bottom:1px solid var(--border);">
      <span style="font-family:'Consolas','Monaco',monospace;font-size:13px;color:var(--accent);min-width:48px;">No.${no}</span>
      <span style="font-size:14px;color:var(--text);">${name}</span>
    </div>`).join('');}
function copyText(text,btn){navigator.clipboard.writeText(text).then(()=>{btn.textContent='✓';setTimeout(()=>btn.textContent='コピー',1500);});}
const countState={create:1,clone:1};function setCount(tab,n,el){countState[tab]=n;el.closest('div').querySelectorAll('.count-btn').forEach(b=>b.classList.remove('active'));el.classList.add('active');}
const accountTypeState={create:'new'};const ACCOUNT_TYPE_DESCRIPTIONS={"new":"初期垢：今まで通りの初期状態から作成します。","beginner":"初心者垢：猫缶800〜2,500・XP80万〜400万。日本編クリア、未来編1章0〜8ステージ。アイテム・お宝・施設・城・ガマトト・神社・プレイ時間も範囲内でランダム。キャラはLv10〜25前後です。","intermediate":"中級者垢：猫缶3,000〜7,000・XP800万〜2,500万。日本・未来編クリア、宇宙編1章8〜20ステージ。レア多め・Lv20〜35前後。チケット・アイテム・施設・城なども毎回変わります。日本編全章と未来編2章までのお宝は、すべて最高で解放済みです。","advanced":"上級者垢：猫缶8,000〜16,000・XP3,500万〜7,500万。宇宙編3章クリア、レジェンド1冠、真レジェ8〜16章、大狂乱クリア相当。レア系多め・Lv30〜50前後。資源・施設・城・お宝・プレイ時間なども範囲内でランダムです。日本編全章と未来編2章までのお宝は、すべて最高で解放済みです。"};function setAccountType(type,el){accountTypeState.create=type;el.closest('div').querySelectorAll('.count-btn').forEach(b=>b.classList.remove('active'));el.classList.add('active');const desc=document.getElementById('account-type-description');if(desc)desc.textContent=ACCOUNT_TYPE_DESCRIPTIONS[type]||'';}
const HISTORY_KEY='nyanko_history';let currentHistTab='daiko';function loadHistory(){try{return JSON.parse(localStorage.getItem(HISTORY_KEY)||'[]').map(e=>{const clean={...e};if(clean.recovery_tc){if(clean.type==='daiko'&&!clean.out_tc){clean.out_tc=clean.recovery_tc;clean.out_ac=clean.recovery_ac||'';}else if(clean.type==='clone'&&!clean.orig_tc){clean.orig_tc=clean.recovery_tc;clean.orig_ac=clean.recovery_ac||'';}}
if(!clean.recovery_failed)delete clean.operation_id;return clean;});}catch{return[];}}
function saveHistory(list){localStorage.setItem(HISTORY_KEY,JSON.stringify(list));}
function addHistory(entry){const list=loadHistory();const oneMonthAgo=Date.now()-30*24*60*60*1000;const filtered=list.filter(e=>e.ts>oneMonthAgo);filtered.unshift({...entry,ts:Date.now()});saveHistory(filtered);}
function clearHistory(){if(!confirm('履歴を全削除しますか？'))return;localStorage.removeItem(HISTORY_KEY);renderHistory();}
function openHistory(){document.getElementById('history-modal').style.display='block';renderHistory();}
function closeHistory(){document.getElementById('history-modal').style.display='none';}
function openTerms(){document.getElementById('terms-modal').style.display='block';}
function closeTerms(){document.getElementById('terms-modal').style.display='none';}
function switchHistTab(tab,el){currentHistTab=tab;document.querySelectorAll('.hist-tab-btn').forEach(b=>{b.style.background='none';b.style.borderColor='var(--border)';b.style.color='var(--muted)';});el.style.background='var(--tag-bg)';el.style.borderColor='var(--accent)';el.style.color='var(--accent)';renderHistory();}
function fmtDate(ts){const d=new Date(ts);return`${d.getFullYear()}/${String(d.getMonth()+1).padStart(2,'0')}/${String(d.getDate()).padStart(2,'0')} ${String(d.getHours()).padStart(2,'0')}:${String(d.getMinutes()).padStart(2,'0')}`;}
function renderHistory(){const list=loadHistory();const oneMonthAgo=Date.now()-30*24*60*60*1000;const filtered=list.filter(e=>e.ts>oneMonthAgo).filter(e=>currentHistTab==='all'||e.type===currentHistTab);const el=document.getElementById('history-list');if(!filtered.length){el.innerHTML='<div style="color:var(--muted);font-size:13px;text-align:center;padding:40px 0;">履歴がありません</div>';return;}
el.innerHTML=filtered.map(e=>{const typeLabel=e.type==='daiko'?'代行':e.type==='create'?'アカウント作成':'複製';const typeColor=e.type==='daiko'?'#60a5fa':e.type==='create'?'var(--success)':'var(--accent)';let codesHtml='';if(e.type==='daiko'){codesHtml=`
        <div style="font-size:11px;color:var(--muted);margin:8px 0 4px;">使用した引き継ぎコード・認証番号</div>
        <div class="code-display" style="margin:0 0 8px;">
          <div class="code-box"><div class="clabel">引き継ぎコード</div><div class="code-val" style="font-size:14px;">${e.in_tc||'—'}<button class="copy-btn" onclick="copyText('${e.in_tc}',this)">コピー</button></div></div>
          <div class="code-box"><div class="clabel">認証番号</div><div class="code-val" style="font-size:14px;">${e.in_ac||'—'}<button class="copy-btn" onclick="copyText('${e.in_ac}',this)">コピー</button></div></div>
        </div>
        <div style="font-size:11px;color:var(--muted);margin-bottom:4px;">代行後の引き継ぎコード・認証番号</div>
        <div class="code-display" style="margin:0;">
          <div class="code-box"><div class="clabel">引き継ぎコード</div><div class="code-val" style="font-size:14px;">${e.out_tc||'—'}<button class="copy-btn" onclick="copyText('${e.out_tc}',this)">コピー</button></div></div>
          <div class="code-box"><div class="clabel">認証番号</div><div class="code-val" style="font-size:14px;">${e.out_ac||'—'}<button class="copy-btn" onclick="copyText('${e.out_ac}',this)">コピー</button></div></div>
        </div>
        ${e.applied && e.applied.length ? `<div style="font-size:11px;color:var(--muted);margin-top:8px;margin-bottom:4px;">適応項目</div><div class="applied-list">${e.applied.map(a=>`<span class="applied-tag">${a}</span>`).join('')}</div>` : ''}`;}else if(e.type==='create'){const accounts=e.accounts||[];codesHtml=accounts.map((acc,i)=>`
        ${accounts.length > 1 ? `<div style="font-size:11px;color:var(--muted);margin:${i===0?'8':'14'}px 0 4px;">アカウント ${i+1}</div>` : '<div style="font-size:11px;color:var(--muted);margin:8px 0 4px;">作成したアカウントの引き継ぎコード・認証番号</div>'}
        <div class="code-display" style="margin:0;">
          <div class="code-box"><div class="clabel">引き継ぎコード</div><div class="code-val" style="font-size:14px;">${acc.tc||'—'}<button class="copy-btn" onclick="copyText('${acc.tc}',this)">コピー</button></div></div>
          <div class="code-box"><div class="clabel">認証番号</div><div class="code-val" style="font-size:14px;">${acc.ac||'—'}<button class="copy-btn" onclick="copyText('${acc.ac}',this)">コピー</button></div></div>
        </div>`).join('');if(e.applied&&e.applied.length){codesHtml+=`<div style="font-size:11px;color:var(--muted);margin-top:8px;margin-bottom:4px;">適応項目</div><div class="applied-list">${e.applied.map(a=>`<span class="applied-tag">${a}</span>`).join('')}</div>`;}}else if(e.type==='clone'){const copies=e.copies||[];codesHtml=`
        <div style="font-size:11px;color:var(--muted);margin:8px 0 4px;">使用した引き継ぎコード・認証番号</div>
        <div class="code-display" style="margin:0 0 8px;">
          <div class="code-box"><div class="clabel">引き継ぎコード</div><div class="code-val" style="font-size:14px;">${e.in_tc||'—'}<button class="copy-btn" onclick="copyText('${e.in_tc}',this)">コピー</button></div></div>
          <div class="code-box"><div class="clabel">認証番号</div><div class="code-val" style="font-size:14px;">${e.in_ac||'—'}<button class="copy-btn" onclick="copyText('${e.in_ac}',this)">コピー</button></div></div>
        </div>
        <div style="font-size:11px;color:var(--muted);margin-bottom:4px;">元のアカウントの引き継ぎコード・認証番号</div>
        <div class="code-display" style="margin:0 0 8px;">
          <div class="code-box"><div class="clabel">引き継ぎコード</div><div class="code-val" style="font-size:14px;">${e.orig_tc||'—'}<button class="copy-btn" onclick="copyText('${e.orig_tc}',this)">コピー</button></div></div>
          <div class="code-box"><div class="clabel">認証番号</div><div class="code-val" style="font-size:14px;">${e.orig_ac||'—'}<button class="copy-btn" onclick="copyText('${e.orig_ac}',this)">コピー</button></div></div>
        </div>
        ${copies.map((c, i) => `<div style="font-size:11px;color:var(--muted);margin-bottom:4px;">${copies.length>1?`複製アカウント ${i+1}`:'複製のアカウントの引き継ぎコード・認証番号'}</div><div class="code-display"style="margin:0 ${i < copies.length-1 ? '0 8px' : ''};"><div class="code-box"><div class="clabel">引き継ぎコード</div><div class="code-val"style="font-size:14px;">${c.tc||'—'}<button class="copy-btn"onclick="copyText('${c.tc}',this)">コピー</button></div></div><div class="code-box"><div class="clabel">認証番号</div><div class="code-val"style="font-size:14px;">${c.ac||'—'}<button class="copy-btn"onclick="copyText('${c.ac}',this)">コピー</button></div></div></div>`).join('')}`;}
return`<div style="background:var(--surface2);border:1px solid var(--border);border-radius:10px;padding:14px 16px;margin-bottom:10px;">
      <div style="display:flex;align-items:center;gap:8px;margin-bottom:6px;">
        <span style="padding:2px 10px;border-radius:99px;font-size:11px;font-weight:700;background:color-mix(in srgb,${typeColor} 15%,transparent);border:1px solid color-mix(in srgb,${typeColor} 40%,transparent);color:${typeColor};">${typeLabel}</span>
        <span style="font-size:11px;color:var(--muted);margin-left:auto;">${fmtDate(e.ts)}</span>
      </div>
      ${e.operation_id && e.recovery_failed ? `<div style="font-size:11px;color:var(--error);margin-bottom:6px;">管理復旧用受付ID:<code>${escChar(e.operation_id)}</code>/管理パネルで再発行が必要</div>` : ''}
      ${e.status==='error' ? `<div class="error-msg">${escChar(e.error||'不明なエラー')}</div>${e.recovery_failed?'<div style="color:var(--error);font-size:11px;">管理パネルで引き継ぎコードを再発行してください</div>':''}` : ''}
      ${codesHtml}
    </div>`;}).join('');}
buildOptions('daiko');buildOptions('create');resumeSavedJobs();observeRunButtons();loadLegendMetadata().then(()=>{buildOptions('daiko');buildOptions('create');}).catch(error=>{console.error(error);document.querySelectorAll('.legend-loading').forEach(el=>{el.textContent=error.message||'ステージ名を読み込めませんでした。';});});async function fetchUsageCount(){try{const res=await fetch('/api/usage_count');if(!res.ok)return;const{count}=await res.json();const el=document.getElementById('usage-count-num');if(el)el.textContent=count.toLocaleString(document.documentElement.lang==='en'?'en-US':'ja-JP');}catch(e){}}
fetchUsageCount();setInterval(fetchUsageCount,5000);